# Hour mentions in the website text become placeholders that the website fills in
# from the Session Booking opening hours, so changing the hours updates every page
TEXT_RULES = [
    (re.compile(r"\b10(?:[:.]00)?\s*am\b", re.I), "{open}"),
    (re.compile(r"\b0?5[:.]30\s*pm\b", re.I), "{close}"),
    (re.compile(r"\bclose at 5\s*pm\b", re.I), "close 30 minutes before we close"),
    (re.compile(r"\bWednesday to Sunday\b|\bWed\s*[-–]\s*Sun(?:day)?\b", re.I), "{days}"),
    (re.compile(r"\bMonday (?:&|and) Tuesday\b|\bMon\s*[-–]\s*Tue(?:sday)?\b", re.I), "{closed_days}"),
    (re.compile(r"\(\{open\}\s*-\s*\{close\}\)"), "({hours})"),
]


def _placeholders(text):
    if not isinstance(text, str):
        return text
    for pattern, repl in TEXT_RULES:
        text = pattern.sub(repl, text)
    return text


